/**
 * SIMPLE-02 — Normalizar inbound Meta WhatsApp Cloud API
 */
const root = $input.first().json;
const body = root.body || root;

try {
  const entry = body.entry?.[0];
  const change = entry?.changes?.[0];
  const value = change?.value;
  const msg = value?.messages?.[0];

  if (!msg) return [];

  // Status updates, delivery receipts, etc.
  if (msg.type !== 'text') {
    // Audios/notas de voz: stub amigable (sin transcripción por ahora)
    if (msg.type === 'audio' || msg.type === 'voice') {
      const phone = String(msg.from || '').replace(/\D/g, '');
      if (!phone) return [];
      const nombre = value.contacts?.[0]?.profile?.name || 'Cliente';
      return [
        {
          json: {
            canal: 'whatsapp',
            chat_id: phone,
            dedupe_key: 'whatsapp:' + phone,
            lead_name: nombre,
            phone: phone,
            mensaje: '',
            es_audio_sin_transcripcion: true,
            waba_message_id: msg.id || '',
            fecha: new Date().toISOString(),
          },
        },
      ];
    }
    return [];
  }

  const phone = String(msg.from || '').replace(/\D/g, '');
  const texto = String(msg.text?.body || '').trim();
  if (!phone || !texto) return [];

  const nombre = value.contacts?.[0]?.profile?.name || 'Cliente';

  return [
    {
      json: {
        canal: 'whatsapp',
        chat_id: phone,
        dedupe_key: 'whatsapp:' + phone,
        lead_name: nombre,
        phone: phone,
        mensaje: texto,
        waba_message_id: msg.id || '',
        fecha: new Date().toISOString(),
      },
    },
  ];
} catch (e) {
  return [];
}

/**
 * Helpers compartidos WA/TG — voz humana, puntuación, anti-repetición.
 * Se concatena al inicio de wa-procesar-ia.js y tg-parsear-respuesta.js vía patch scripts.
 */

function sanitizarPuntuacion(texto) {
  let t = String(texto || '').trim();
  if (!t) return t;
  t = t.replace(/¿/g, '');
  t = t.replace(/…/g, '');
  t = t.replace(/\.{3,}/g, '');
  t = t.replace(/\.{2}/g, '.');
  t = t.replace(/!+/g, '');
  t = t.replace(/\.\s*$/g, '');
  t = t.replace(/\s+([,?])/g, '$1');
  t = t.replace(/\s{2,}/g, ' ').trim();
  return t;
}

function formatearPresuMil(presuNum) {
  const n = Number(presuNum) || 0;
  return n >= 1000 ? Math.round(n / 1000) + ' mil' : String(n || '');
}

function normalizarTexto(texto) {
  return String(texto || '')
    .toLowerCase()
    .replace(/[^a-záéíóúñ0-9\s]/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function similitudTexto(a, b) {
  const na = normalizarTexto(a);
  const nb = normalizarTexto(b);
  if (!na || !nb) return 0;
  if (na === nb) return 1;
  const wa = na.split(' ').filter((w) => w.length > 2);
  const wb = new Set(nb.split(' ').filter((w) => w.length > 2));
  if (!wa.length || !wb.size) return 0;
  let inter = 0;
  for (const w of wa) if (wb.has(w)) inter++;
  return inter / Math.max(wa.length, wb.size);
}

function esSimilar(a, b, umbral) {
  return similitudTexto(a, b) >= (umbral || 0.68);
}

function parseHistorialArr(raw) {
  if (Array.isArray(raw)) return raw;
  try {
    if (typeof raw === 'string' && raw.trim()) return JSON.parse(raw);
  } catch (e) {}
  return [];
}

function obtenerMensajesBot(historialArr) {
  if (!Array.isArray(historialArr)) return [];
  return historialArr
    .filter((m) => {
      const role = String((m && m.role) || '').toLowerCase();
      return role === 'assistant' || role === 'bot';
    })
    .map((m) => String((m && m.content) || '').trim())
    .filter(Boolean);
}

function obtenerMensajesUsuario(historialArr) {
  if (!Array.isArray(historialArr)) return [];
  return historialArr
    .filter((m) => {
      const role = String((m && m.role) || '').toLowerCase();
      return role === 'user' || role === 'cliente';
    })
    .map((m) => String((m && m.content) || '').trim())
    .filter(Boolean);
}

function esConsultaRepetida(mensaje, historialArr) {
  const actual = String(mensaje || '').trim();
  if (!actual) return false;
  const prev = obtenerMensajesUsuario(historialArr);
  if (!prev.length) return false;
  return prev.slice(-4).some((p) => esSimilar(actual, p, 0.62));
}

function contarBotsSimilares(texto, historialArr) {
  const bots = obtenerMensajesBot(historialArr);
  return bots.filter((b) => esSimilar(texto, b, 0.55)).length;
}

function armarMensajeAlquilerVsCompra(presuNum, zona, variantIdx) {
  const mil = formatearPresuMil(presuNum);
  const zonaBit = zona && zona !== '(no indicó)' ? ' en ' + zona : '';
  const v = Number(variantIdx) || 0;
  const variantes = [
    'Con ' +
      mil +
      ' dólares podemos mirar opciones de compra' +
      zonaBit +
      '. Buscás comprar o alquilar? Si es alquiler, el presupuesto mensual suele expresarse en pesos; contame un poco más y te oriento',
    'Ya lo hablamos: con ese monto en dólares lo usual' +
      zonaBit +
      ' es compra. Si buscás alquiler, pasame el tope mensual en pesos y vemos qué hay',
    'Para no marearte, ' +
      mil +
      ' USD' +
      zonaBit +
      ' entra en compra. Querés que te muestre opciones o preferís alquiler en pesos?',
  ];
  return sanitizarPuntuacion(variantes[v % variantes.length]);
}

function humanizarVoz(texto) {
  let t = String(texto || '').trim();
  t = t.replace(/^¡?\s*hey[!,.]?\s*/i, '');
  t = t.replace(/^¡+/g, '');
  t = t.replace(/\bUf\b[,.]*\s*/gi, '');
  t = t.replace(/\bno me cierra\b[^.?!]*/gi, '');
  t = t.replace(
    /\b(estoy a tu disposici[oó]n|qued[oó] a tu disposici[oó]n|mi especialidad es[^.!?]*)\b/gi,
    '',
  );
  t = t.replace(
    /\b(con gusto (estoy|quedo) para ayudarte|cualquier cosa que necesites,? estoy ac[aá])\b/gi,
    '',
  );
  t = t.replace(
    /\b(?:te contacta|se pone en contacto) un asesor\b[^.?!]*/gi,
    'te escribo yo',
  );
  t = t.replace(
    /\¿?\s*Te gustar[ií]a que un asesor(?: de Nodo Propiedades)? te contacte[^.!?]*[.!?]?\s*/gi,
    '',
  );
  t = t.replace(
    /\b(?:cuando haya opciones que )?encaj(?:en|an) con tu b[uú]squeda\b[^.!?]*/gi,
    '',
  );
  t = t.replace(
    /\b(?:para poder ayudarte|ayudarte mejor|me gustar[ií]a saber|ser[ií]a ideal si)\b[^.!?]*/gi,
    '',
  );
  t = t.replace(
    /\b(?:no tengo inmuebles|no hay inmuebles) disponibles(?: en este momento)?\b/gi,
    'ahora mismo no tengo nada con ese pedido',
  );
  t = t.replace(
    /\bno tengo inmuebles disponibles en este momento\b/gi,
    'ahora mismo no tengo nada con ese pedido',
  );
  t = t.replace(
    /\bun asesor(?: de Nodo Propiedades)? (?:te |se ponga en )?contact/gi,
    'te escribo yo',
  );
  t = t.replace(
    /\b(quedo a las [oó]rdenes|recibido|confirmado|procedo a|a sus [oó]rdenes)\b/gi,
    '',
  );
  t = t.replace(/\b[Cc]he\b[,.;:!?]*\s*/g, '');
  t = t.replace(/\s{2,}/g, ' ').trim();
  t = t.replace(/^[,.\s]+/, '').trim();
  return sanitizarPuntuacion(t);
}

function suenaPlantillaRobot(texto) {
  return /\b(te gustar[ií]a que un asesor|estoy a tu disposici[oó]n|mi especialidad es|encaj(?:en|an) con tu b[uú]squeda|no tengo inmuebles disponibles en este momento|se ponga en contacto con vos|te contacta un asesor|quedo a las [oó]rdenes)\b/i.test(
    String(texto || ''),
  );
}

function reescribirSiRobot(texto, zona, presupuesto, variantIdx) {
  const t = String(texto || '');
  if (!suenaPlantillaRobot(t) && !/\bun asesor de Nodo\b/i.test(t)) {
    return humanizarVoz(t);
  }
  const presuNum = presupuesto ? Number(presupuesto) : 0;
  const zonaBit = zona && zona !== '(no indicó)' ? zona : zona || '';
  if (/\balquil/i.test(t) && presuNum >= 15000) {
    return armarMensajeAlquilerVsCompra(presuNum, zonaBit, variantIdx || 0);
  }
  if (/\bno tengo|sin (opciones|stock|disponib)|no (hay|encuentro)/i.test(t)) {
    const zb = zonaBit ? ' en ' + zonaBit : '';
    const sinStock = [
      'Ahora mismo no tengo nada' + zb + ' con ese tope, aflojamos un poco el presupuesto o miramos otra zona?',
      'Con ese tope' + zb + ' no me queda stock hoy, probamos otra zona o ajustamos el presupuesto?',
    ];
    return sanitizarPuntuacion(sinStock[(variantIdx || 0) % sinStock.length]);
  }
  return humanizarVoz(t);
}

function evitarRepeticion(respuesta, opts) {
  const o = opts || {};
  let out = String(respuesta || '').trim();
  if (!out) return out;

  const historialArr = parseHistorialArr(o.historialArr || o.historial_json_prev);
  const bots = obtenerMensajesBot(historialArr);
  const ultimoBot = bots.length ? bots[bots.length - 1] : '';
  const consultaRep = esConsultaRepetida(o.mensajeUsuario, historialArr);
  const respuestaRep =
    (ultimoBot && esSimilar(out, ultimoBot, 0.68)) ||
    bots.slice(-3).some((b) => esSimilar(out, b, 0.72));
  const repCount = contarBotsSimilares(out, historialArr);

  if (!respuestaRep && !consultaRep) return out;

  const variantIdx = Math.max(repCount, consultaRep ? 1 : 0, bots.length % 3);

  if (o.esAlquilerPresupuestoAlto) {
    return armarMensajeAlquilerVsCompra(
      o.presupuestoDetectado,
      o.zonaDetectada,
      variantIdx,
    );
  }

  if (consultaRep && ultimoBot && esSimilar(out, ultimoBot, 0.5)) {
    const reconocimientos = [
      'Como te decía, ',
      'Retomando, ',
      'Sin repetir todo, ',
    ];
    const pref = reconocimientos[variantIdx % reconocimientos.length];
    const cuerpo = out.charAt(0).toLowerCase() + out.slice(1);
    return sanitizarPuntuacion(pref + cuerpo);
  }

  if (respuestaRep) {
    return reescribirSiRobot(out, o.zonaDetectada, o.presupuestoDetectado, variantIdx);
  }

  return out;
}

function quitarMuletillaChe(texto) {
  if (!texto || typeof texto !== 'string') return texto;
  return sanitizarPuntuacion(
    texto.replace(/\b[Cc]he\b[,.;:!?]*\s*/g, '').replace(/\s{2,}/g, ' ').trim(),
  );
}

/** Respuesta del bot demasiado informal/slang para guardar como ejemplo de Matías */
function respuestaInformalExcesiva(texto) {
  const t = String(texto || '').toLowerCase();
  if (!t) return true;
  if (/\b(che|boludo|boluda|loco|loca|pibe|mina|re\s+\w+|posta|al toque|zarpado)\b/i.test(t)) {
    return true;
  }
  if (/\b(jajaja|jaja|xd|lol)\b/i.test(t) && t.length < 80) return true;
  return false;
}

/** ¿Sirve como ejemplo de aprendizaje? (profesional-cercano, no plantilla robot) */
function respuestaAptaParaAprendizaje(texto) {
  const t = String(texto || '').trim();
  if (!t || t.length < 15) return false;
  if (respuestaInformalExcesiva(t)) return false;
  if (suenaPlantillaRobot(t)) return false;
  if (/\b(solo trabajo con propiedades|no puedo ayudarte con eso)\b/i.test(t) && t.length < 60) {
    return false;
  }
  return true;
}

/**
 * Clasificador de intención Matías — heurísticas combinadas (sin segundo call IA).
 * Se concatena antes de bot-aprendizaje.js vía patch scripts.
 */

const IC_ZONAS = [
  'godoy cruz',
  'guaymallen',
  'guaymallén',
  'capital',
  'lujan',
  'luján',
  'maipu',
  'maipú',
  'las heras',
  'san martin',
  'san martín',
  'mendoza',
];

const IC_ACK =
  /^(ok|dale|gracias|si|sí|no|bueno|perfecto|listo|jajaja|jaja|hola|buen[oa]s?|👍|🙏|de una|genial|bárbaro|barbaro|copado)\s*[!.?]*$/i;

const IC_OFF_TOPIC_DURO =
  /\b(comer|comida|restaurante|almorzar|cenar|desayun|hambur|pizza|asado|birra|cerveza|hambre|necesito comer|d[oó]nde (puedo|se puede) comer|receta|cocinar)\b/i;

const IC_PERSONAL_CLARO =
  /\b(hermano|hermana|mam[aá]|pap[aá]|salimos|tomamos|llamame al personal|no es por una propiedad|netflix|partido de f[uú]tbol)\b/i;

const IC_INMO_KEYWORDS =
  /\b(depto|departamento|casa|lote|local|oficina|alquiler|alquil|comprar|compra|venta|vender|propiedad|propiedades|inmueble|inmobiliaria|presupuesto|habitaci[oó]n|dormitorio|ambientes|m2|zona|barrio|visita|usd|u\$s|dolar|mza-\d+|nodo|expensas|cochera|escritur)\b/i;

const IC_PEDIR_OPCIONES =
  /\b(que ten[eé]s|qué ten[eé]s|que hay|qué hay|que venden|qué venden|mostrame|mostrá|mandame|mandá|pasame|pasá|opciones|catalogo|catálogo|enviame|enviá|algo para ver|ver algo|lo que tengas|lo que tengan|mandame algo|mostrame algo|sorprendeme|sorprendeme)\b/i;

const IC_SIN_CRITERIO =
  /\b(no tengo (nada )?(claro|en mente|definido)|no s[eé] (tanto|mucho|bien|nada)?|nose|no estoy seguro|sin criterio|sin idea|no defin[ií]|a[uú]n no s[eé]|todav[ií]a no s[eé]|me da igual|cualquier cosa|cualquiera)\b/i;

const IC_CURIOSO =
  /\b(solo (estoy )?(viendo|mirando|curioseando)|solo quiero ver|de curioso|por curiosidad|para ver nomas|para saber nomas|nomas (quiero|para) ver|cu[aá]nto sale|a cu[aá]nto|precio de|cu[aá]nto cuesta)\b/i;

const IC_VISITA =
  /\b(visita|verla|verlo|agendar|turno|recorrer|conocerla|conocerlo|s[aá]bado|domingo|pasar a ver)\b/i;

const IC_REFINAR =
  /\b(m[aá]s barato|m[aá]s caro|otra zona|otro barrio|m[aá]s grande|m[aá]s chico|menos|hasta|tope|refin|filtr|solo en|busco en)\b/i;

function icNormalizar(texto) {
  return String(texto || '')
    .toLowerCase()
    .replace(/[^a-záéíóúñ0-9\s]/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function icExtraerPresupuestoUsd(texto) {
  const t = String(texto || '').toLowerCase();
  let m = t.match(
    /(\d{1,3}(?:[.\s]\d{3})+|\d{4,7})\s*(?:usd|u\$s|dolar(?:es)?|dolares)/i,
  );
  if (m) return parseInt(m[1].replace(/[.\s]/g, ''), 10);
  m = t.match(/(\d{2,3})\s*mil\s*(?:usd|u\$s|dolar(?:es)?)?/i);
  if (m) return parseInt(m[1], 10) * 1000;
  m = t.match(/\b(\d{2,3})k\b/i);
  if (m) return parseInt(m[1], 10) * 1000;
  m = t.match(/por\s+(\d{1,3}(?:[.\s]\d{3})+|\d{4,7})/i);
  if (m) return parseInt(m[1].replace(/[.\s]/g, ''), 10);
  m = t.match(/(\d{2,3})\s*mil\b/i);
  if (m && !/\b(alquil|mensual|por mes)\b/i.test(t)) return parseInt(m[1], 10) * 1000;
  return null;
}

function icExtraerZona(texto) {
  const t = icNormalizar(texto);
  for (const z of IC_ZONAS) {
    if (t.includes(z)) return z;
  }
  return '';
}

function icExtraerOperacion(texto) {
  const t = String(texto || '').toLowerCase();
  if (/\b(alquil|rent|alquiler)\b/i.test(t)) return 'alquiler';
  if (/\b(compr|venta|vend|compra)\b/i.test(t)) return 'compra';
  return '';
}

function icYaMostroStock(historialTexto, historialArr) {
  const bots = [];
  if (Array.isArray(historialArr)) {
    for (const m of historialArr) {
      const role = String((m && m.role) || '').toLowerCase();
      if (role === 'assistant' || role === 'bot') {
        bots.push(String((m && m.content) || ''));
      }
    }
  }
  const h = (historialTexto || '') + ' ' + bots.join(' ');
  return /###MOSTRAR_PROPIEDADES###|te paso un par de opciones|mirá estas opciones|cuál te llama más/i.test(
    h,
  );
}

function icEsSaludoVacio(msg) {
  const m = String(msg || '').trim();
  return m.length > 0 && m.length < 30 && IC_ACK.test(m);
}

function clasificarIntencionCliente(msg, historial, opts) {
  const o = opts || {};
  const texto = String(msg || '').trim();
  const hist = String(historial || '').trim();
  const textoCompleto = (hist + '\n' + texto).trim();
  const esAudio = Boolean(o.esAudioSinTexto);

  if (esAudio) {
    return {
      intencion: 'audio',
      confianza: 'alta',
      mostrar_stock: false,
      modo_curioso: false,
      requiere_calificar: false,
      es_off_topic: false,
      es_saludo: false,
      presupuesto_usd: null,
      zona: '',
      operacion: '',
    };
  }

  const presupuestoUsd =
    icExtraerPresupuestoUsd(texto) || icExtraerPresupuestoUsd(hist);
  const zona = icExtraerZona(texto) || icExtraerZona(hist);
  const operacion = icExtraerOperacion(texto) || icExtraerOperacion(hist);
  const yaMostroStock = icYaMostroStock(hist, o.historialJsonArr);
  const esSaludo = icEsSaludoVacio(texto);

  let scoreInmo = 0;
  if (presupuestoUsd) scoreInmo += 4;
  if (zona) scoreInmo += 3;
  if (operacion) scoreInmo += 2;
  if (IC_INMO_KEYWORDS.test(texto)) scoreInmo += 3;
  if (IC_PEDIR_OPCIONES.test(texto)) scoreInmo += 4;
  if (IC_SIN_CRITERIO.test(texto)) scoreInmo += 3;
  if (IC_CURIOSO.test(texto)) scoreInmo += 2;
  if (IC_VISITA.test(texto)) scoreInmo += 3;
  if (IC_INMO_KEYWORDS.test(hist)) scoreInmo += 1;
  if (/\b(busco|necesito|quiero|tengo)\b/i.test(texto) && texto.length >= 8) scoreInmo += 1;

  let scoreOff = 0;
  if (IC_OFF_TOPIC_DURO.test(texto)) scoreOff += 5;
  if (IC_PERSONAL_CLARO.test(texto)) scoreOff += 4;
  if (scoreInmo >= 2) scoreOff = Math.max(0, scoreOff - 3);

  const pideOpciones =
    IC_PEDIR_OPCIONES.test(texto) ||
    IC_SIN_CRITERIO.test(texto) ||
    IC_CURIOSO.test(texto);
  let modoCurioso =
    IC_SIN_CRITERIO.test(texto) ||
    IC_CURIOSO.test(texto) ||
    (pideOpciones && !presupuestoUsd && !zona) ||
    (texto.length < 55 && IC_PEDIR_OPCIONES.test(texto));

  let mostrarStock =
    Boolean(o.stockDisponible !== false && o.stockDisponible !== 0) &&
    !(
      operacion === 'alquiler' &&
      presupuestoUsd &&
      presupuestoUsd >= 15000
    ) &&
    (pideOpciones ||
      Boolean(presupuestoUsd) ||
      modoCurioso ||
      (scoreInmo >= 3 && !esSaludo));

  const requiereCalificar =
    yaMostroStock &&
    !pideOpciones &&
    !IC_SIN_CRITERIO.test(texto) &&
    (IC_REFINAR.test(texto) ||
      (Boolean(zona) && IC_INMO_KEYWORDS.test(texto)) ||
      (Boolean(presupuestoUsd) && !modoCurioso));

  if (requiereCalificar && !IC_PEDIR_OPCIONES.test(texto)) {
    mostrarStock = Boolean(presupuestoUsd || IC_REFINAR.test(texto));
  }

  let intencion = 'explorar';
  if (esSaludo && scoreInmo < 2) intencion = 'saludo';
  else if (IC_VISITA.test(texto)) intencion = 'visita';
  else if (presupuestoUsd && !pideOpciones) intencion = 'presupuesto';
  else if (zona && !pideOpciones && !modoCurioso) intencion = 'consulta_zona';
  else if (pideOpciones || IC_SIN_CRITERIO.test(texto)) intencion = 'pedir_opciones';
  else if (modoCurioso) intencion = 'explorar';
  else if (scoreOff >= 5 && scoreInmo < 2) intencion = 'off_topic';

  let confianza = 'media';
  if (scoreInmo >= 5 || scoreOff >= 5 || esSaludo) confianza = 'alta';
  else if (scoreInmo <= 1 && scoreOff <= 1 && texto.length > 3) confianza = 'baja';

  if (confianza === 'baja' && intencion !== 'off_topic' && intencion !== 'saludo') {
    mostrarStock = Boolean(o.stockDisponible !== false && o.stockDisponible !== 0);
    if (mostrarStock && !requiereCalificar) {
      modoCurioso = true;
    }
  }

  let esOffTopic = false;
  if (scoreOff >= 5 && scoreInmo < 2 && !mostrarStock && !esSaludo) {
    esOffTopic = true;
    intencion = 'off_topic';
  }
  if (mostrarStock) esOffTopic = false;

  return {
    intencion,
    confianza,
    mostrar_stock: mostrarStock,
    modo_curioso: modoCurioso,
    requiere_calificar: requiereCalificar,
    es_off_topic: esOffTopic,
    es_saludo: esSaludo,
    presupuesto_usd: presupuestoUsd,
    zona,
    operacion,
    score_inmo: scoreInmo,
    score_off: scoreOff,
  };
}

function formatearBloqueIntencionPrompt(clasif) {
  const c = clasif || {};
  const lines = [
    'INTENCION_DETECTADA (clasificador automático — seguí esto; no contradigas mostrar_stock=true):',
    JSON.stringify({
      intencion: c.intencion,
      confianza: c.confianza,
      mostrar_stock: c.mostrar_stock,
      modo_curioso: c.modo_curioso,
