  propiedadesMostrar = [];
  mensajeCierre = '';
  solicitudVisita = false;
} else if (mensajesExtra.length > 1) {
  respuesta = mensajesExtra[0];
  mensajesExtra = mensajesExtra.slice(1);
} else if (mensajesExtra.length === 1 && !respuesta) {
  respuesta = mensajesExtra[0];
